def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    src = int(ctx.p.lg_src)
    if src == 0:
        p = [float(b["c"]) for b in bars]
    elif src == 2:
        p = [(float(b["h"]) + float(b["l"]) + float(b["c"])) / 3.0 for b in bars]
    else:
        p = [(float(b["h"]) + float(b["l"])) / 2.0 for b in bars]

    g = float(ctx.p.lg_gamma)
    L0 = L1 = L2 = L3 = p[0]
    out = [None] * n
    prev = 0.5
    for i in range(1, n):
        n0 = (1.0 - g) * p[i] + g * L0
        n1 = -g * n0 + L0 + g * L1
        n2 = -g * n1 + L1 + g * L2
        n3 = -g * n2 + L2 + g * L3
        L0, L1, L2, L3 = n0, n1, n2, n3
        cu = 0.0
        cd = 0.0
        if L0 >= L1:
            cu += L0 - L1
        else:
            cd += L1 - L0
        if L1 >= L2:
            cu += L1 - L2
        else:
            cd += L2 - L1
        if L2 >= L3:
            cu += L2 - L3
        else:
            cd += L3 - L2
        t = cu + cd
        v = cu / t if t > 0 else prev
        prev = v
        out[i] = v
    ctx.lr = ctx.series(out, "laguerre_rsi")


def signal(ctx, i):
    v = ctx.lr[i]
    if v is None:
        return 0
    lo = float(ctx.p.rail)
    hi = 1.0 - lo
    k = max(2, int(ctx.p.pinned))
    if i <= k:
        return 0
    if v > lo:
        pinned = True
        for z in range(1, k + 1):
            u = ctx.lr[i - z]
            if u is None or u > lo:
                pinned = False
                break
        if pinned:
            return 1
    if v < hi:
        pinned = True
        for z in range(1, k + 1):
            u = ctx.lr[i - z]
            if u is None or u < hi:
                pinned = False
                break
        if pinned:
            return -1
    return 0


def exit_signal(ctx, i):
    v = ctx.lr[i]
    if v is None or not ctx.positions:
        return False
    lo = float(ctx.p.rail)
    ex = float(ctx.p.exit_rail)
    if ctx.positions[0]["side"] == "long":
        return v >= ex or v <= lo
    return v <= 1.0 - ex or v >= 1.0 - lo
